/* Path-tracking demo UI.
 *
 * Loads docs/data/reference.json (generated by tools/build_web_data.py from the
 * repository's own simulator) and drives docs/engine.js, which is a browser port
 * of the same vehicle model, controller, reward and observation code.
 *
 * Two execution modes are offered:
 *
 *   ref  (default)  the recorded steering commands from the Python run are
 *                   replayed through the browser-side dynamics.  Because these
 *                   commands are stored in the data set, this mode can be
 *                   compared element-by-element against the reference, and the
 *                   page reports the worst deviation it measured.
 *   loop            the controller is recomputed in the browser at every step
 *                   (closed loop), which exercises controller + vehicle + reward
 *                   with nothing but the path and the start pose taken from the
 *                   data set.
 */
(function () {
  "use strict";

  var DATA_URL = "data/reference.json";
  var WORLD = 600;          // simulator workspace spans 0..600 in both axes
  var REF_COLOR = "#8a93a6";
  var RUN_COLOR = "#2fd6c3";
  var LOOP_COLOR = "#ffb454";

  var state = {
    data: null,
    scenario: null,
    result: null,
    mode: "ref",
    index: 0,
    playing: false,
    speed: 2,
    lastFrame: 0,
    parity: null
  };

  var dom = {};

  /* ------------------------------------------------------------------ *
   * Data loading and verification
   * ------------------------------------------------------------------ */

  function fetchJson(url) {
    return fetch(url, { cache: "no-cache" }).then(function (r) {
      if (!r.ok) {
        throw new Error("cannot load " + url + " (HTTP " + r.status + ")");
      }
      return r.json();
    });
  }

  function maxAbsDiff(a, b, cols) {
    if (!a || !b || a.length !== b.length) {
      return Infinity;
    }
    var worst = 0;
    for (var i = 0; i < a.length; i++) {
      for (var c = 0; c < cols; c++) {
        var d = Math.abs(a[i][c] - b[i][c]);
        if (d > worst) {
          worst = d;
        }
      }
    }
    return worst;
  }

  function maxAbsDiffFlat(a, b) {
    if (!a || !b || a.length !== b.length) {
      return Infinity;
    }
    var worst = 0;
    for (var i = 0; i < a.length; i++) {
      var d = Math.abs(a[i] - b[i]);
      if (d > worst) {
        worst = d;
      }
    }
    return worst;
  }

  /* Re-runs every recorded episode in the browser and measures how far the
   * browser engine drifts from the stored Python trace. */
  function verifyAll() {
    var report = { traj: 0, reward: 0, obs: 0, worst: null, returns: [] };
    state.data.scenarios.forEach(function (sc) {
      var ep = window.RNE.runEpisode(sc, { mode: "replay" });
      var dTraj = maxAbsDiff(ep.trajectory, sc.trajectory, 4);
      var dRew = maxAbsDiffFlat(ep.rewards, sc.rewards);
      var dObs = maxAbsDiff(ep.observation, sc.observation, ep.observation[0].length);
      report.returns.push({
        id: sc.id,
        reference: sc.summary.return,
        browser: ep.totalReward,
        diff: Math.abs(sc.summary.return - ep.totalReward)
      });
      if (dTraj > report.traj) { report.traj = dTraj; report.worst = sc.id; }
      if (dRew > report.reward) { report.reward = dRew; }
      if (dObs > report.obs) { report.obs = dObs; }
    });
    state.parity = report;
  }

  /* ------------------------------------------------------------------ *
   * Episode preparation
   * ------------------------------------------------------------------ */

  function runSelected() {
    var sc = state.scenario;
    var mode = state.mode === "loop" ? "closed-loop" : "replay";
    state.result = window.RNE.runEpisode(sc, { mode: mode });
    state.index = 0;

    // Closed-loop runs can drift from the recorded run; keep both visible by
    // reporting the largest lateral deviation against the reference trace.
    var dev = 0;
    var n = Math.min(state.result.trajectory.length, sc.trajectory.length);
    for (var i = 0; i < n; i++) {
      var d = Math.hypot(
        state.result.trajectory[i][0] - sc.trajectory[i][0],
        state.result.trajectory[i][1] - sc.trajectory[i][1]
      );
      if (d > dev) {
        dev = d;
      }
    }
    state.deviation = dev;
    // Replay runs reproduce the stored diagnostics exactly; closed-loop runs
    // compute distance, heading error and progress in the browser, so the
    // readout follows whichever episode is currently on screen.
    state.diagnostics = state.result.minDist ? state.result : sc;
    render();
  }

  /* ------------------------------------------------------------------ *
   * Rendering
   * ------------------------------------------------------------------ */

  function toScreen(p) {
    // The simulator works in a y-up frame; the canvas is y-down.
    return [p[0], WORLD - p[1]];
  }

  function setupCanvas() {
    var canvas = dom.canvas;
    var dpr = window.devicePixelRatio || 1;
    canvas.width = WORLD * dpr;
    canvas.height = WORLD * dpr;
    canvas.style.width = WORLD + "px";
    canvas.style.height = WORLD + "px";
    dom.ctx = canvas.getContext("2d");
    dom.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }

  function drawGrid(ctx) {
    ctx.fillStyle = "#0e1420";
    ctx.fillRect(0, 0, WORLD, WORLD);
    ctx.strokeStyle = "#1b2536";
    ctx.lineWidth = 1;
    for (var g = 0; g <= WORLD; g += 50) {
      ctx.beginPath();
      ctx.moveTo(g + 0.5, 0);
      ctx.lineTo(g + 0.5, WORLD);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, g + 0.5);
      ctx.lineTo(WORLD, g + 0.5);
      ctx.stroke();
    }
  }

  function drawPolyline(ctx, pts, color, width, upto) {
    var n = upto === undefined ? pts.length : Math.min(upto, pts.length);
    if (n < 2) {
      return;
    }
    ctx.beginPath();
    var p0 = toScreen(pts[0]);
    ctx.moveTo(p0[0], p0[1]);
    for (var i = 1; i < n; i++) {
      var p = toScreen(pts[i]);
      ctx.lineTo(p[0], p[1]);
    }
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.lineJoin = "round";
    ctx.stroke();
  }

  function drawVehicle(ctx, pose) {
    var p = toScreen(pose);
    ctx.save();
    ctx.translate(p[0], p[1]);
    ctx.rotate(-pose[2] * Math.PI / 180.0);  // yaw is measured in the y-up frame
    ctx.fillStyle = "#ffffff";
    ctx.beginPath();
    ctx.moveTo(11, 0);
    ctx.lineTo(-7, 6);
    ctx.lineTo(-7, -6);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function drawScenario(ctx) {
    var sc = state.scenario;
    drawGrid(ctx);

    // control points
    ctx.fillStyle = "#4d5b73";
    sc.controlPoints.forEach(function (p) {
      var q = toScreen(p);
      ctx.fillRect(q[0] - 3, q[1] - 3, 6, 6);
    });

    // reference path
    drawPolyline(ctx, sc.path, REF_COLOR, 2);

    // the run being animated
    var color = state.mode === "loop" ? LOOP_COLOR : RUN_COLOR;
    if (state.mode === "loop") {
      drawPolyline(ctx, sc.trajectory, "rgba(138,147,166,0.35)", 2);
    }
    var traj = state.result.trajectory;
    drawPolyline(ctx, traj, color, 3, state.index + 1);

    // start and goal
    var start = toScreen(sc.start);
    ctx.strokeStyle = "#5b6b85";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(start[0], start[1], 7, 0, Math.PI * 2);
    ctx.stroke();

    var goal = toScreen(sc.path[sc.path.length - 1]);
    ctx.strokeStyle = "#e04f6a";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(goal[0], goal[1], 8, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(goal[0] - 12, goal[1]);
    ctx.lineTo(goal[0] + 12, goal[1]);
    ctx.moveTo(goal[0], goal[1] - 12);
    ctx.lineTo(goal[0], goal[1] + 12);
    ctx.stroke();

    if (state.index < traj.length) {
      drawVehicle(ctx, traj[state.index]);
    }
  }

  function fmt(v, digits) {
    if (v === undefined || v === null || !isFinite(v)) {
      return "—";
    }
    return v.toFixed(digits === undefined ? 3 : digits);
  }

  function renderReadout() {
    var sc = state.scenario;
    var ep = state.result;
    var diag = state.diagnostics || sc;
    var i = Math.min(state.index, ep.rewards.length - 1);
    var cum = 0;
    for (var k = 0; k <= i; k++) {
      cum += ep.rewards[k];
    }
    var rows = [
      ["step", (i + 1) + " / " + ep.steps],
      ["cumulative reward", fmt(cum, 2)],
      ["reward of step", fmt(ep.rewards[i], 3)],
      ["distance to path (min)", fmt(diag.minDist[i], 3)],
      ["heading error (deg)", fmt(diag.errorYaw[i], 3)],
      ["progress term", fmt(diag.progress[i], 1)],
      ["episode return", fmt(ep.totalReward, 2)],
      ["termination", ep.doneReason]
    ];
    dom.readout.innerHTML = rows.map(function (r) {
      return '<div class="row"><span>' + r[0] + "</span><b>" + r[1] + "</b></div>";
    }).join("");
  }

  function render() {
    drawScenario(dom.ctx);
    renderReadout();
    dom.scrub.max = String(Math.max(state.result.steps - 1, 0));
    dom.scrub.value = String(state.index);
    dom.play.textContent = state.playing ? "Pause" : "Play";
    dom.modeLabel.textContent = state.mode === "loop" ? "closed loop (browser)" : "replay (recorded commands)";
    dom.scenarioInfo.innerHTML =
      "<b>" + state.scenario.name + "</b> · " + state.scenario.controller +
      "<br><span class='muted'>" + state.scenario.description + "</span>";
    if (state.mode === "loop") {
      dom.deviation.textContent =
        "max deviation from the recorded trace: " + fmt(state.deviation, 4) + " units";
    } else {
      dom.deviation.textContent =
        "recorded commands replayed through the browser dynamics";
    }
  }

  /* ------------------------------------------------------------------ *
   * Animation
   * ------------------------------------------------------------------ */

  function tick(ts) {
    if (!state.playing) {
      return;
    }
    if (!state.lastFrame) {
      state.lastFrame = ts;
    }
    var dt = (ts - state.lastFrame) / 1000;
    if (dt >= 1 / (30 * state.speed)) {
      state.lastFrame = ts;
      state.index += 1;
      if (state.index >= state.result.steps) {
        state.index = state.result.steps - 1;
        state.playing = false;
      }
      render();
    }
    window.requestAnimationFrame(tick);
  }

  function togglePlay() {
    state.playing = !state.playing;
    if (state.playing) {
      if (state.index >= state.result.steps - 1) {
        state.index = 0;
      }
      state.lastFrame = 0;
      window.requestAnimationFrame(tick);
    }
    render();
  }

  /* ------------------------------------------------------------------ *
   * Wiring
   * ------------------------------------------------------------------ */

  function buildScenarioButtons() {
    dom.scenarios.innerHTML = "";
    state.data.scenarios.forEach(function (sc, idx) {
      var b = document.createElement("button");
      b.className = "tab";
      b.textContent = sc.name;
      b.addEventListener("click", function () {
        state.scenario = sc;
        Array.prototype.forEach.call(dom.scenarios.children, function (c) {
          c.classList.remove("active");
        });
        b.classList.add("active");
        state.playing = false;
        runSelected();
      });
      if (idx === 0) {
        b.classList.add("active");
      }
      dom.scenarios.appendChild(b);
    });
    state.scenario = state.data.scenarios[0];
  }

  function renderParity() {
    var p = state.parity;
    var worstReturn = 0;
    p.returns.forEach(function (r) {
      if (r.diff > worstReturn) {
        worstReturn = r.diff;
      }
    });
    var lines = [
      ["trajectory (x, y, yaw, v)", p.traj],
      ["per-step reward", p.reward],
      ["observation vector", p.obs]
    ].map(function (r) {
      return '<div class="row"><span>' + r[0] + " max |Δ|</span><b>" +
        (r[1] === 0 ? "0.0 (exact)" : r[1].toExponential(2)) + "</b></div>";
    }).join("");
    dom.parity.innerHTML =
      lines +
      '<div class="row"><span>episode return max |Δ|</span><b>' +
      (worstReturn === 0 ? "0.0 (exact)" : worstReturn.toExponential(2)) + "</b></div>" +
      '<p class="muted small">Worst case over all ' + p.returns.length +
      " recorded episodes, computed in this browser session by replaying the stored " +
      "steering commands through docs/engine.js and comparing against " +
      "docs/data/reference.json.</p>";
  }

  function fail(err) {
    dom.readout.innerHTML = '<div class="row"><span>error</span><b>' +
      String(err && err.message ? err.message : err) + "</b></div>";
  }

  function main() {
    dom.canvas = document.getElementById("canvas");
    dom.readout = document.getElementById("readout");
    dom.parity = document.getElementById("parity");
    dom.scenarios = document.getElementById("scenarios");
    dom.scrub = document.getElementById("scrub");
    dom.play = document.getElementById("play");
    dom.stepBtn = document.getElementById("step");
    dom.reset = document.getElementById("reset");
    dom.speed = document.getElementById("speed");
    dom.mode = document.getElementById("mode");
    dom.modeLabel = document.getElementById("modeLabel");
    dom.scenarioInfo = document.getElementById("scenarioInfo");
    dom.deviation = document.getElementById("deviation");
    dom.status = document.getElementById("status");

    setupCanvas();

    fetchJson(DATA_URL).then(function (data) {
      state.data = data;
      if (!window.RNE) {
        throw new Error("engine.js did not load");
      }
      verifyAll();
      buildScenarioButtons();
      runSelected();
      renderParity();
      dom.status.textContent =
        "engine " + window.RNE.version + " · " + data.scenarios.length +
        " recorded episodes · simulator: " + data.meta.simulatorType + " kinematic model";
      dom.status.classList.add("ok");
    }).catch(function (err) {
      dom.status.textContent = "failed to initialise: " + err.message;
      dom.status.classList.add("bad");
      fail(err);
    });

    dom.play.addEventListener("click", togglePlay);
    dom.stepBtn.addEventListener("click", function () {
      state.playing = false;
      state.index = Math.min(state.index + 1, state.result.steps - 1);
      render();
    });
    dom.reset.addEventListener("click", function () {
      state.playing = false;
      state.index = 0;
      render();
    });
    dom.scrub.addEventListener("input", function () {
      state.playing = false;
      state.index = parseInt(dom.scrub.value, 10) || 0;
      render();
    });
    dom.speed.addEventListener("change", function () {
      state.speed = parseFloat(dom.speed.value);
    });
    dom.mode.addEventListener("change", function () {
      state.mode = dom.mode.value;
      state.playing = false;
      runSelected();
    });

    if ("serviceWorker" in navigator && location.protocol === "https:") {
      navigator.serviceWorker.register("sw.js").catch(function () { /* offline shell is optional */ });
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", main);
  } else {
    main();
  }
})();
